                                                 ds.Tables["Menu"].Columns["MenuID"],
                                                 ds.Tables["Menu"].Columns["ParentID"],
                                                 false);

        relation.Nested = true;
        ds.Relations.Add(relation);

        return ds.GetXml();
    }

